const input = $input.first().json;
const op = input.operation;
const d = input.data || {};

const str = (v) => (v === null || v === undefined || v === '') ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const int = (v) => { const n = Number.parseInt(v, 10); if (Number.isNaN(n)) throw new Error('Gia tri INT khong hop le: ' + v); return String(n); };
const intOrNull = (v) => (v === null || v === undefined || v === '') ? 'NULL' : int(v);
const num = (v) => { if (v === null || v === undefined || v === '') return 'NULL'; const n = Number(v); if (!Number.isFinite(n)) throw new Error('Gia tri so khong hop le: ' + v); return String(n); };
const bit = (v) => (v === true || v === 1 || v === '1' || v === 'true') ? 'true' : 'false';
const dt = (v) => { if (v === null || v === undefined || v === '') return 'NULL'; const s = String(v); if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(s)) throw new Error('Datetime phai dang YYYY-MM-DD HH:mm:ss: ' + s); return "'" + s + "'::timestamp"; };
const js = (v) => (v === null || v === undefined) ? 'NULL' : str(typeof v === 'string' ? v : JSON.stringify(v));
const D = (col) => "TO_CHAR(" + col + ", 'YYYY-MM-DD HH24:MI:SS')";
const EV_COLS = `event_id, request_id, user_id, title, location, ${D('start_time')} AS start_time, ${D('end_time')} AS end_time, google_event_id, status`;

let sql = null;
let build_error = null;
try {
  switch (op) {
    case 'get_user':
      sql = `SELECT user_id, email AS external_user_id, full_name, timezone FROM users WHERE email = ${str(d.external_user_id || d.email)};`;
      break;
    case 'insert_request':
      sql = `INSERT INTO schedule_requests (user_id, user_command, intent, parsed_json, status) VALUES (${int(d.user_id)}, ${str(d.user_command)}, ${str(d.intent || 'unknown')}, ${js(d.parsed_json)}, ${str(d.status || 'proposals_ready')}) RETURNING request_id, status;`;
      break;
    case 'update_request':
      sql = `UPDATE schedule_requests SET status = ${str(d.status)}, parsed_json = COALESCE(${js(d.parsed_json)}, parsed_json) WHERE request_id = ${int(d.request_id)} RETURNING request_id, status;`;
      break;
    case 'get_request':
      sql = `SELECT r.request_id, r.user_id, u.email AS external_user_id, r.user_command, r.intent, r.parsed_json, r.status, ${D('r.created_at')} AS created_at FROM schedule_requests r JOIN users u ON u.user_id = r.user_id WHERE r.request_id = ${int(d.request_id)};`;
      break;
    case 'insert_slots': {
      if (!Array.isArray(d.slots) || d.slots.length === 0) throw new Error('slots rong');
      const ttl = int(d.expires_in_minutes ?? 30);
      const round = int(d.proposal_round ?? 1);
      const rid = int(d.request_id);
      const values = d.slots.map((s) => `(${rid}, ${str(s.slot_code)}, ${round}, ${dt(s.start_time)}, ${dt(s.end_time)}, ${bit(s.is_outdoor)}, ${intOrNull(s.rain_probability)}, ${bit(s.is_suitable ?? true)}, ${num(s.score)}, 'pending', NOW() + INTERVAL '${ttl} minutes')`).join(', ');
      sql = `INSERT INTO proposed_slots (request_id, slot_code, proposal_round, start_time, end_time, is_outdoor, rain_probability, is_suitable, score, status, expires_at) VALUES ${values} RETURNING slot_id, slot_code, ${D('start_time')} AS start_time, ${D('end_time')} AS end_time, status, ${D('expires_at')} AS expires_at;`;
      break;
    }
    case 'get_slots':
      sql = `SELECT slot_id, slot_code, ${D('start_time')} AS start_time, ${D('end_time')} AS end_time, is_outdoor, rain_probability, is_suitable, score, status, ${D('expires_at')} AS expires_at FROM proposed_slots WHERE request_id = ${int(d.request_id)} AND status = ${str(d.status || 'pending')} ORDER BY slot_code;`;
      break;
    case 'get_slot':
      sql = `SELECT slot_code, status, ${D('start_time')} AS start_time, ${D('end_time')} AS end_time, CASE WHEN expires_at <= NOW() THEN 1 ELSE 0 END AS is_expired FROM proposed_slots WHERE request_id = ${int(d.request_id)} AND slot_code = ${str(d.slot_code)};`;
      break;
    case 'lock_slot': {
      const allowed = d.allow_retry ? "'pending', 'failed', 'slot_taken'" : "'pending'";
      sql = `UPDATE proposed_slots SET status = 'confirming' WHERE request_id = ${int(d.request_id)} AND slot_code = ${str(d.slot_code)} AND status IN (${allowed}) AND expires_at > NOW() RETURNING slot_id, slot_code, ${D('start_time')} AS start_time, ${D('end_time')} AS end_time;`;
      break;
    }
    case 'update_slot_status':
      sql = `UPDATE proposed_slots SET status = ${str(d.status)} WHERE request_id = ${int(d.request_id)} AND slot_code = ${str(d.slot_code)} RETURNING slot_code, status;`;
      break;
    case 'find_event': {
      const c = [];
      if (!d.google_event_id && !d.request_id && !d.title_like) throw new Error('find_event can google_event_id, request_id hoac title_like');
      if (d.google_event_id) c.push(`e.google_event_id = ${str(d.google_event_id)}`);
      if (d.request_id) c.push(`e.request_id = ${int(d.request_id)}`);
      if (d.external_user_id) c.push(`u.email = ${str(d.external_user_id)}`);
      if (d.title_like) { const esc = String(d.title_like).replace(/'/g, "''"); c.push(`e.title ILIKE '%${esc}%'`); }
      if (d.on_date) { if (!/^\d{4}-\d{2}-\d{2}$/.test(String(d.on_date))) throw new Error('on_date phai dang YYYY-MM-DD'); c.push(`e.start_time::date = '${d.on_date}'`); }
      if (!d.include_deleted) c.push("e.status <> 'deleted'");
      sql = `SELECT e.event_id, e.request_id, e.user_id, u.email AS external_user_id, e.title, e.location, ${D('e.start_time')} AS start_time, ${D('e.end_time')} AS end_time, e.google_event_id, e.status FROM events e JOIN users u ON u.user_id = e.user_id WHERE ${c.join(' AND ')} ORDER BY e.start_time LIMIT 10;`;
      break;
    }
    case 'insert_event': {
      const g = str(d.google_event_id);
      if (g === 'NULL') throw new Error('thieu google_event_id');
      sql = `INSERT INTO events (request_id, user_id, title, location, start_time, end_time, google_event_id, status) VALUES (${intOrNull(d.request_id)}, ${int(d.user_id)}, ${str(d.title)}, ${str(d.location)}, ${dt(d.start_time)}, ${dt(d.end_time)}, ${g}, 'active') ON CONFLICT (google_event_id) DO UPDATE SET title = EXCLUDED.title RETURNING ${EV_COLS};`;
      break;
    }
    case 'update_event': {
      if (!d.google_event_id) throw new Error('thieu google_event_id');
      const g = str(d.google_event_id);
      const sets = [];
      if (d.title) sets.push(`title = ${str(d.title)}`);
      if (d.location) sets.push(`location = ${str(d.location)}`);
      if (d.start_time) sets.push(`start_time = ${dt(d.start_time)}`);
      if (d.end_time) sets.push(`end_time = ${dt(d.end_time)}`);
      sets.push("status = 'updated'");
      sql = `UPDATE events SET ${sets.join(', ')} WHERE google_event_id = ${g} AND status <> 'deleted' RETURNING ${EV_COLS};`;
      break;
    }
    case 'delete_event': {
      if (!d.google_event_id) throw new Error('thieu google_event_id');
      const g = str(d.google_event_id);
      sql = `WITH del_rem AS (DELETE FROM reminders WHERE trang_thai = 'pending' AND event_id IN (SELECT event_id FROM events WHERE google_event_id = ${g})) UPDATE events SET status = 'deleted' WHERE google_event_id = ${g} RETURNING event_id, google_event_id, status;`;
      break;
    }
    case 'insert_reminder': {
      const e = int(d.event_id);
      sql = `INSERT INTO reminders (event_id, thoi_gian_nhac, noi_dung_nhac, trang_thai) VALUES (${e}, ${dt(d.thoi_gian_nhac)}, ${str(d.noi_dung_nhac)}, 'pending') RETURNING id, event_id, ${D('thoi_gian_nhac')} AS thoi_gian_nhac, trang_thai;`;
      break;
    }
    case 'finalize_create': {
      const r = int(d.request_id);
      const s = str(d.slot_code);
      sql = `WITH u1 AS (UPDATE proposed_slots SET status = 'created' WHERE request_id = ${r} AND slot_code = ${s}), u2 AS (INSERT INTO session_logs (user_command, ai_analysis_json, selected_slot, google_event_id, status) VALUES (${str(d.user_command)}, ${js(d.ai_analysis_json)}, ${s}, ${str(d.google_event_id)}, 'created')) UPDATE schedule_requests SET status = 'created' WHERE request_id = ${r} RETURNING request_id, status;`;
      break;
    }
    case 'insert_weather_logs': {
      if (!Array.isArray(d.rows) || d.rows.length === 0) throw new Error('rows rong');
      const rows = d.rows.slice(0, 400).map((r) => `(${str(r.location)}, ${dt(r.forecast_time)}, ${num(r.temperature)}, ${intOrNull(r.precipitation_probability)}, ${num(r.rain_mm)})`).join(', ');
      sql = `INSERT INTO weather_logs (location, forecast_time, temperature, precipitation_probability, rain_mm) VALUES ${rows} RETURNING id;`;
      break;
    }
    case 'get_habit_hours':
      sql = `SELECT EXTRACT(HOUR FROM e.start_time) AS hour_of_day, COUNT(*) AS cnt FROM events e JOIN users u ON u.user_id = e.user_id WHERE u.email = ${str(d.external_user_id)} AND e.status <> 'deleted' GROUP BY EXTRACT(HOUR FROM e.start_time) ORDER BY COUNT(*) DESC LIMIT 3;`;
      break;
    case 'log_session':
      sql = `INSERT INTO session_logs (user_command, ai_analysis_json, proposed_slots_json, selected_slot, google_event_id, status, error_message) VALUES (${str(d.user_command)}, ${js(d.ai_analysis_json)}, ${js(d.proposed_slots_json)}, ${str(d.selected_slot)}, ${str(d.google_event_id)}, ${str(d.status)}, ${str(d.error_message)}) RETURNING id;`;
      break;
    case 'process_due_reminders': {
      const lim = int(d.limit ?? 200);
      sql = `WITH due AS (UPDATE reminders SET trang_thai = 'processed' WHERE id IN (SELECT id FROM reminders WHERE trang_thai = 'pending' AND thoi_gian_nhac <= NOW() ORDER BY thoi_gian_nhac LIMIT ${lim} FOR UPDATE SKIP LOCKED) RETURNING id, event_id, noi_dung_nhac, thoi_gian_nhac), lg AS (INSERT INTO session_logs (user_command, ai_analysis_json, status) SELECT 'system:reminder_processed', json_build_object('reminder_id', id, 'event_id', event_id, 'noi_dung', noi_dung_nhac)::text, 'reminder_processed' FROM due) SELECT id, event_id, noi_dung_nhac, ${D('thoi_gian_nhac')} AS thoi_gian_nhac FROM due;`;
      break;
    }
    default:
      throw new Error('Operation khong ho tro: ' + op);
  }
} catch (e) {
  build_error = e.message;
}
return [{ json: { operation: op, sql, build_error } }];

const meta = $('Build SQL').first().json;
const items = $input.all().map((i) => i.json);

if (meta.build_error) {
  return [{ json: { success: false, operation: meta.operation, error: meta.build_error, rows_count: 0, rows: [] } }];
}
const err = items.find((j) => j && j.error);
if (err) {
  const msg = typeof err.error === 'string' ? err.error : (err.error.message || JSON.stringify(err.error));
  return [{ json: { success: false, operation: meta.operation, error: msg, rows_count: 0, rows: [] } }];
}
const rows = items.filter((j) => j && Object.keys(j).length > 0 && !j.skipped);
return [{ json: { success: true, operation: meta.operation, rows_count: rows.length, rows } }];
